        else { cue_set_status("版本 A 还没有内容；先写一版再存 A。") }
        return
    }
    cue_read_mode = 2
    cue_take_read = slot
    cue_ws_page = 0
    cue_pause_playback()
    cue_rebuild_ws()
    cue_sync_reader()
    if slot == 1 { cue_set_status("正在看版本 B。") }
    else { cue_set_status("正在看版本 A。") }
}

